import { afterEach, beforeAll, describe, expect, it, jest } from "@jest/globals";
import { DataSource, SelectQueryBuilder } from "typeorm";
import { Property } from "database/models/Property";
import { Property_Moderation_Event } from "database/models/Property_Moderation_Event";
import { Property_Location } from "database/models/Property_Location";
import {
  afterListingPosition,
  findListingPosition,
  joinLatestApproval,
  orderByListingPosition,
} from "../../functions/PropertyHandler/data/repository/listingPosition.js";

// The SQL is generated by the real TypeORM query builder. No connection is opened, so these tests prove the
// shape of the query, not the order of rows a database returns for it.
describe("listing position query", () => {
  let dataSource;

  const render = () => {
    const query = dataSource.getRepository(Property).createQueryBuilder("property");
    const positioned = orderByListingPosition(joinLatestApproval(query));
    return { sql: positioned.getQuery(), parameters: positioned.getParameters() };
  };

  beforeAll(async () => {
    dataSource = new DataSource({
      type: "postgres",
      schema: "test",
      entities: [Property, Property_Moderation_Event, Property_Location],
    });
    await dataSource.buildMetadatas();
  });

  it("joins the latest approval of every property once, as an aggregate", () => {
    const { sql } = render();

    expect(sql).toContain(
      'LEFT JOIN (SELECT "event"."property_id" AS "property_id", MAX("event"."created_at") AS "approved_at" ' +
        'FROM "test"."property_moderation_event" "event"'
    );
    expect(sql).toContain('GROUP BY "event"."property_id") "approval" ON approval.property_id = "property"."id"');
  });

  it("counts APPROVED events only", () => {
    const { sql, parameters } = render();

    expect(sql).toContain('WHERE "event"."action" = :approvedAction');
    expect(parameters).toEqual({ approvedAction: "APPROVED" });
  });

  it("reads zero as the approval time of a property that was never approved", () => {
    const { sql } = render();

    expect(sql).toContain('COALESCE(approval.approved_at, 0) AS "approved_at"');
  });

  it("sorts oldest approval first, then newest listing first, then id descending", () => {
    const { sql } = render();

    expect(sql).toContain('ORDER BY approved_at ASC, "property"."createdat" DESC, "property"."id" DESC');
  });

  it("keeps the aggregate independent of the property rows, so it runs once per query", () => {
    const { sql } = render();
    const aggregate = sql.slice(sql.indexOf("LEFT JOIN ("), sql.indexOf(') "approval"'));

    expect(aggregate).toContain("MAX(");
    expect(aggregate).not.toContain('"property"');
  });
});

describe("keyset position", () => {
  let dataSource;
  let captured;

  beforeAll(async () => {
    dataSource = new DataSource({
      type: "postgres",
      schema: "test",
      entities: [Property, Property_Moderation_Event, Property_Location],
    });
    await dataSource.buildMetadatas();
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  describe("afterListingPosition", () => {
    const position = { approvedAt: 5000, createdAt: 1700000000100, id: "property-6" };

    const render = () => {
      const query = joinLatestApproval(dataSource.getRepository(Property).createQueryBuilder("property"));
      const after = afterListingPosition(query, position);
      return { sql: after.getQuery(), parameters: after.getParameters() };
    };

    it("keeps the rows that sort after the position, in three nested branches", () => {
      const { sql } = render();

      expect(sql).toContain(
        "WHERE (COALESCE(approval.approved_at, 0) > :cursorApprovedAt" +
          ' OR (COALESCE(approval.approved_at, 0) = :cursorApprovedAt AND "property"."createdat" < :cursorCreatedAt)' +
          " OR (COALESCE(approval.approved_at, 0) = :cursorApprovedAt" +
          ' AND "property"."createdat" = :cursorCreatedAt AND "property"."id" < :cursorId))'
      );
    });

    it("binds the three position values and nothing else of its own", () => {
      const { parameters } = render();

      expect(parameters).toEqual({
        approvedAction: "APPROVED",
        cursorApprovedAt: 5000,
        cursorCreatedAt: 1700000000100,
        cursorId: "property-6",
      });
    });
  });

  describe("findListingPosition", () => {
    const read = async (row) => {
      jest.spyOn(SelectQueryBuilder.prototype, "getRawOne").mockImplementation(function () {
        captured = { sql: this.getQuery(), parameters: this.getParameters() };
        return Promise.resolve(row);
      });
      return await findListingPosition(dataSource, "property-6");
    };

    it("reads the row by id and does not filter on status", async () => {
      await read({ property_id: "property-6", property_createdat: "1", approved_at: "0" });

      expect(captured.sql).toContain('WHERE "property"."id" = :id');
      expect(captured.sql).not.toContain('"property"."status"');
      expect(captured.parameters.id).toBe("property-6");
    });

    it("looks up the latest APPROVED event of that one row", async () => {
      await read({ property_id: "property-6", property_createdat: "1", approved_at: "0" });

      expect(captured.sql).toContain('COALESCE(MAX("event"."created_at"), 0)');
      expect(captured.sql).toContain('"event"."property_id" = "property"."id" AND "event"."action" = :approvedAction');
      expect(captured.parameters.approvedAction).toBe("APPROVED");
    });

    it("returns numbers, because the driver hands bigint back as text", async () => {
      const position = await read({
        property_id: "property-6",
        property_createdat: "1700000000100",
        approved_at: "1700000005000",
      });

      expect(position).toEqual({ approvedAt: 1700000005000, createdAt: 1700000000100, id: "property-6" });
    });

    it("reads a never-approved row as approvedAt zero", async () => {
      const position = await read({ property_id: "property-6", property_createdat: "5", approved_at: "0" });

      expect(position.approvedAt).toBe(0);
    });

    it("returns null when no row has that id", async () => {
      await expect(read(undefined)).resolves.toBeNull();
    });
  });

  describe("findListingPosition with a scope", () => {
    const inCountry = (lookup) =>
      lookup
        .innerJoin("property_location", "pl", "pl.property_id = property.id")
        .andWhere("pl.country = :country", { country: "Germany" });

    const readScoped = async (scope, row = { property_id: "property-6", property_createdat: "5", approved_at: "0" }) => {
      jest.spyOn(SelectQueryBuilder.prototype, "getRawOne").mockImplementation(function () {
        captured = { sql: this.getQuery(), parameters: this.getParameters() };
        return Promise.resolve(row);
      });
      return await findListingPosition(dataSource, "property-6", scope);
    };

    it("adds the scope's join and filter to the lookup", async () => {
      await readScoped(inCountry);

      expect(captured.sql).toContain('INNER JOIN "test"."property_location" "pl" ON "pl"."property_id" = "property"."id"');
      expect(captured.sql).toContain('WHERE "property"."id" = :id AND "pl"."country" = :country');
      expect(captured.parameters.country).toBe("Germany");
    });

    it("still looks the row up by id when a scope is given", async () => {
      await readScoped(inCountry);

      expect(captured.sql).toContain('"property"."id" = :id');
      expect(captured.parameters.id).toBe("property-6");
    });

    it("returns the position of a row that passes the scope", async () => {
      const position = await readScoped(inCountry, {
        property_id: "property-6",
        property_createdat: "1700000000100",
        approved_at: "1700000005000",
      });

      expect(position).toEqual({ approvedAt: 1700000005000, createdAt: 1700000000100, id: "property-6" });
    });

    it("returns null for a row the scope filters out, the same as for a row that does not exist", async () => {
      await expect(readScoped(inCountry, null)).resolves.toBeNull();
    });

    describe("a scope that weakens the lookup", () => {
      const OTHER_ROW = { property_id: "some-other-property", property_createdat: "5", approved_at: "0" };

      it("is a real weakening: a scope using where() leaves no id filter in the query", async () => {
        await readScoped((lookup) => lookup.where("1 = 1"), OTHER_ROW);

        expect(captured.sql).not.toContain('"property"."id" = :id');
      });

      it("is a real broadening: a scope using orWhere() ORs the id filter with something else", async () => {
        await readScoped((lookup) => lookup.orWhere("property.status = 'ACTIVE'"), OTHER_ROW);

        expect(captured.sql).toContain('"property"."id" = :id OR');
      });

      it("returns null when a scope that dropped the id filter lets a different row through", async () => {
        await expect(readScoped((lookup) => lookup.where("1 = 1"), OTHER_ROW)).resolves.toBeNull();
      });

      it("returns null when a scope that broadened the id filter lets a different row through", async () => {
        await expect(
          readScoped((lookup) => lookup.orWhere("property.status = 'ACTIVE'"), OTHER_ROW)
        ).resolves.toBeNull();
      });

      it("returns null for a different row even when no scope is given", async () => {
        await expect(readScoped(undefined, OTHER_ROW)).resolves.toBeNull();
      });

      it("still returns the position when the row is the one asked for, whatever the scope", async () => {
        const position = await readScoped(inCountry, {
          property_id: "property-6",
          property_createdat: "1700000000100",
          approved_at: "1700000005000",
        });

        expect(position).toEqual({ approvedAt: 1700000005000, createdAt: 1700000000100, id: "property-6" });
      });
    });

    it("leaves the lookup unscoped when no scope is given", async () => {
      await readScoped(undefined);

      expect(captured.sql).not.toContain("property_location");
      expect(captured.sql).not.toContain("INNER JOIN");
    });
  });
});
